export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const sub=(a,b)=>a.map((v,i)=>v-b[i]),dot=(a,b)=>a.reduce((s,v,i)=>s+v*b[i],0),cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]],norm=a=>{const n=Math.hypot(...a);return a.map(v=>v/(n||1));};
export function multiply(a,b){const o=new Float32Array(16);for(let c=0;c<4;c++)for(let r=0;r<4;r++)for(let k=0;k<4;k++)o[c*4+r]+=a[k*4+r]*b[c*4+k];return o;}
export function perspective(fov,aspect,near=.1,far=100){const f=1/Math.tan(fov/2),o=new Float32Array(16);o[0]=f/aspect;o[5]=f;o[10]=(far+near)/(near-far);o[11]=-1;o[14]=2*far*near/(near-far);return o;}
export function lookAt(eye,target){const z=norm(sub(eye,target)),x=norm(cross([0,1,0],z)),y=cross(z,x);return new Float32Array([x[0],y[0],z[0],0,x[1],y[1],z[1],0,x[2],y[2],z[2],0,-dot(x,eye),-dot(y,eye),-dot(z,eye),1]);}
export function invert(m){const a=Array.from({length:4},(_,r)=>[...Array.from({length:4},(_,c)=>m[c*4+r]),...Array.from({length:4},(_,c)=>c===r?1:0)]);for(let c=0;c<4;c++){let p=c;for(let r=c+1;r<4;r++)if(Math.abs(a[r][c])>Math.abs(a[p][c]))p=r;if(Math.abs(a[p][c])<1e-10)return null;[a[c],a[p]]=[a[p],a[c]];const d=a[c][c];a[c]=a[c].map(v=>v/d);for(let r=0;r<4;r++)if(r!==c){const f=a[r][c];a[r]=a[r].map((v,i)=>v-f*a[c][i]);}}return new Float32Array(Array.from({length:16},(_,i)=>a[i%4][4+Math.floor(i/4)]));}
export function transform(m,p){const v=[p[0],p[1],p[2],p[3]??1],o=Array.from({length:4},(_,r)=>v.reduce((s,x,c)=>s+m[c*4+r]*x,0));return o.map((v,i)=>i<3?v/o[3]:o[3]);}
export function screenRay(vp,nx,ny){const inverse=invert(vp);if(!inverse)return null;const a=transform(inverse,[nx,ny,-1]).slice(0,3),b=transform(inverse,[nx,ny,1]).slice(0,3);return {origin:a,direction:norm(sub(b,a))};}   // 2026-10-19: 3D vectors only (the projection's w made every pick NaN)
export function groundHit(ray){if(!ray||Math.abs(ray.direction[1])<1e-8)return null;const t=-ray.origin[1]/ray.direction[1];if(t<0)return null;return ray.origin.map((v,i)=>v+t*ray.direction[i]);}
export function wallFraction(from,to,wall,height=1.85){if(wall.open)return null;const [[x1,z1],[x2,z2]]=wall.points,dx=to[0]-from[0],dz=to[2]-from[2];let t,other;if(x1===x2){if(Math.abs(dx)<1e-9)return null;t=(x1-from[0])/dx;other=from[2]+t*dz;if(other<Math.min(z1,z2)-.1||other>Math.max(z1,z2)+.1)return null;}else{if(Math.abs(dz)<1e-9)return null;t=(z1-from[2])/dz;other=from[0]+t*dx;if(other<Math.min(x1,x2)-.1||other>Math.max(x1,x2)+.1)return null;}const y=from[1]+t*(to[1]-from[1]);return t>0&&t<1&&y>=0&&y<height?t:null;}
// 2026-10-19 (Claude): a wall behind the character lifts the camera over it (up to a steep look-down) instead of
// pushing it into the party; a wall's own height (wall.top, from its room's ceiling) is used when given.
export function cameraPose(actor,yaw=0,pitch=.42,distance=7,walls=[]){const target=[actor.x,Math.min(1.1,actor.space_ft/5*.65)+(actor.elev??0),actor.y],d=clamp(distance,2,16),p0=clamp(pitch,.12,1.15);const at=p=>{const desired=[target[0]+Math.sin(yaw)*Math.cos(p)*d,target[1]+Math.sin(p)*d,target[2]+Math.cos(yaw)*Math.cos(p)*d];let fraction=1;for(const wall of walls){const t=wallFraction(target,desired,wall,(wall.top??1.85)+.2);if(t!=null)fraction=Math.min(fraction,Math.max(.08,t-.06));}return {desired,fraction};};let best=null;for(let p=p0;p<=1.15+1e-9;p+=.08){const r=at(p);if(!best||r.fraction>best.fraction+1e-9)best=r;if(r.fraction>=.999)break;}return {target,eye:target.map((v,i)=>v+(best.desired[i]-v)*best.fraction),yaw};}
// 2026-10-21 (GM: Hero 4 "had 7 targets for firebolt but was unable to target any of them"): rank(a), lower first, picks
// among every figure on the line, nearest within a rank; a held attack ranks legal foes first, so a tall ally in front of
// a goblin no longer takes the click.
export function pickActor(ray,actors,yaw,walls=[],rank=()=>0){if(!ray)return null;const normal=[Math.sin(yaw),0,Math.cos(yaw)],right=[Math.cos(yaw),0,-Math.sin(yaw)];let best=null;for(const a of actors){const size=a.space_ft/5,lift=a.elev??0,centre=[a.x,size*.7+lift,a.y],denom=dot(ray.direction,normal);if(Math.abs(denom)<1e-8)continue;const t=dot(sub(centre,ray.origin),normal)/denom;if(t<0)continue;const r=rank(a);if(r===Infinity)continue;if(best&&(r>best.r||(r===best.r&&t>=best.t)))continue;const point=ray.origin.map((v,i)=>v+t*ray.direction[i]),offset=sub(point,centre);if(Math.abs(dot(offset,right))>size*.5||point[1]<lift||point[1]>lift+size*1.4)continue;if(walls.some(w=>wallFraction(ray.origin,point,w)!=null))continue;best={actor:a,t,r};}return best?.actor??null;}
export function movementAt(point,view,selected){if(!point||selected!==view.state.active)return null;const a=view.state.combatants.find(a=>a.id===view.state.active);if(!a)return null;const x=a.x+Math.round(point[0]-a.x),y=a.y+Math.round(point[2]-a.y);return view.movement_targets.find(t=>Math.abs(t.x-x)<1e-8&&Math.abs(t.y-y)<1e-8)??null;}

// 2026-10-19 (Claude, LIVE-PLAY-01 3D): the camera yaw that puts the camera behind `actor`, looking toward the nearest
// creature on another side that is not down (null when there is none). cameraPose puts the eye at
// target + (sin(yaw), ., cos(yaw)) * distance, so behind means yaw = atan2(-dx, -dz) for the direction (dx, dz) to the foe.
export function behindYaw(actor,combatants){let best=null;for(const c of combatants){if(c.id===actor.id||c.down||c.side===actor.side)continue;const d=Math.hypot(c.x-actor.x,c.y-actor.y);if(d>0&&(!best||d<best.d))best={c,d};}return best?Math.atan2(-(best.c.x-actor.x),-(best.c.y-actor.y)):null;}

// 2026-10-19 (GM: ceilings "described and have height to match the building or environment"): the room ceiling over
// square (x, y) from map.ceilings ({room, rect [x1,y1,x2,y2] inclusive, ft or null for open sky, description}), or null.
export function ceilingAt(map,x,y){const sx=Math.round(x),sy=Math.round(y);for(const c of map?.ceilings??[]){const [a,b,cc,d]=c.rect;if(sx>=a&&sx<=cc&&sy>=b&&sy<=d)return c;}return null;}
// 2026-10-19 (GM: "in 3d mode, flying creatures should appear elevated"): how high to draw a creature, in squares (5 ft).
// The simulator keeps no altitude: aloft (over a drop) = 10 ft; able to fly now = a 3-ft hover; never through the
// ceiling (its head stays a little under it). Display only: reach and rules come from the simulator.
export function elevation(a,map){if(a.down)return 0;if(a.rider_lift)return a.rider_lift;   // MAP-LAYERS-01: a rider sits up on its mount
const want=a.aloft?2:a.flying?.6:0;if(!want)return 0;const c=ceilingAt(map,a.x,a.y);if(c?.ft==null)return want;return Math.max(0,Math.min(want,c.ft/5-a.space_ft/5*1.4-.1));}
